        ["scr.pc.turn_bridges"] = "Поворотные мосты",
        ["scr.pc.turn_bridges.tip"] = "Мост над квадратной ямой, который по таймеру поворачивается на четверть и соединяет то одни берега, то другие",
        ["scr.pc.trapdoors"] = "Проваливающийся пол",
