        ["scr.pc.geysers"] = "Лавовые гейзеры",
        ["scr.pc.geysers.tip"] = "Столб лавы, который по таймеру бьёт вверх из отверстия в полу зала",
        ["scr.pc.lasers"] = "Лазерные заслоны",
        ["scr.pc.lasers.tip"] = "Лучи поперёк прохода, которые включаются и гаснут по таймеру — проскочить в паузу; задел — больно",
        ["scr.pc.pistons"] = "Поршни в проходе",
        ["scr.pc.pistons.tip"] = "Блоки, которые по очереди выходят из стен или опускаются с потолка прохода — пробегать в такт",
        ["scr.pc.pendulums"] = "Маятники над мостами",
        ["scr.pc.pendulums.tip"] = "Маятник качается над мостом через яму и сбивает вниз",
        ["scr.pc.drills"] = "Буровые установки",
        ["scr.pc.drills.tip"] = "Вышка над буром, который вращается и уходит в пол: задевает - больно; по буру ездит хомут, у его подножия летят искры, слышен бур. Вышка - четыре опоры, А-образная рама, крестовина или портал",
        ["scr.pc.cogs"] = "Шестерни на стенах",
        ["scr.pc.cogs.tip"] = "Две-три сцепленные шестерни высоко на стене зала крутятся навстречу друг другу со скоростью по числу зубьев, слышна машина",
        ["scr.pc.turrets"] = "Турели в проходах",
        ["scr.pc.turrets.tip"] = "Бластеры в стене прохода стреляют поперёк него по очереди - пробегать между выстрелами",
        ["scr.pc.conveyors"] = "Конвейеры с грузами",
        ["scr.pc.conveyors.tip"] = "Лента вдоль стены зала (на полу или на уступе), ящики или бочки выезжают по ней из короба у одной стены и уезжают в короб у другой, как на q2dm8; на них можно прокатиться",
        ["scr.pc.pendulum_kind"] = "Вид маятника",
        ["scr.pc.pendulum_kind.tip"] = "Головка маятника: молот, двуглавая кувалда, молот с шипами, топор, двойной топор, серп, булава, дисковая пила или якорь; по умолчанию - разные. Рукоять, размах и размеры каждый раз свои",
        ["scr.pc.pendulum_kind.hammer"] = "Молот",
        ["scr.pc.pendulum_kind.sledge"] = "Двуглавая кувалда",
        ["scr.pc.pendulum_kind.spiked"] = "Молот с шипами",
        ["scr.pc.pendulum_kind.axe"] = "Топор",
        ["scr.pc.pendulum_kind.labrys"] = "Двойной топор",
        ["scr.pc.pendulum_kind.sickle"] = "Серп",
        ["scr.pc.pendulum_kind.mace"] = "Булава",
        ["scr.pc.pendulum_kind.saw"] = "Дисковая пила",
        ["scr.pc.pendulum_kind.anchor"] = "Якорь",
        ["scr.pc.hammer_blast"] = "Удар маятника с ударной волной",
        ["scr.pc.hammer_blast.tip"] = "Внизу дуги удар сопровождает вспышка, и волна отбрасывает того, кого задело, тем сильнее, чем больше головка. Без этого маятник толкает и ранит, но не отбрасывает: в самой игре отбросить может только взрыв",
        ["scr.pc.piece_motion"] = "Движение конструкций",
        ["scr.pc.piece_motion.tip"] = "Плавно: поршни, плиты, стены, створки и столбы разгоняются и тормозят, как настоящие. Ровно: с постоянной скоростью, как на известных картах. Вращение в игре всегда ровное",
        ["scr.pc.piece_motion.smooth"] = "Плавно, с разгоном и торможением",
        ["scr.pc.piece_motion.even"] = "Ровно",
        ["scr.pc.shutters"] = "Створки по таймеру",
        ["scr.pc.shutters.tip"] = "Створки в проходе к комнате с ценным предметом открываются и закрываются по таймеру, как над квадом на q2dm6",
        ["scr.pc.pickup_walls"] = "Стены от взятого предмета",
        ["scr.pc.pickup_walls.tip"] = "Взял ценный предмет — рядом опускается стена и открывает короткий путь, как на q2dm6 у красной брони: на время или насовсем",
        ["scr.pc.bent_bridges"] = "Изогнутые мосты",
        ["scr.pc.bent_bridges.tip"] = "Узкий мост с поворотами через яму с лавой или кислотой, как на q2dm4",
        ["scr.pc.wall_steps"] = "Ступени по стене",
