        ["scr.pc.pool_ladders"] = "Лесенки из бассейнов",
        ["scr.pc.pool_ladders.tip"] = "На стенке каждого глубокого бассейна лесенка со дна на край, как на q2dm4",
        ["scr.pc.piece_speed"] = "Скорость конструкций",
        ["scr.pc.piece_speed.tip"] = "Насколько быстрее или медленнее известных карт ездят, вращаются и закрываются конструкции",
