        ["scr.stack"] = "Броня и стек",
        ["scr.stack.tip"] = "Набор главных предметов: красная броня и мега далеко друг от друга; на общий бой — ещё и квад; мега, адреналин и две жёлтые; две жёлтые, адреналин и квад",
        ["scr.stack.ra_mh"] = "Красная броня и мега",
