        ["scr.round"] = "Скругления",
        ["scr.round.tip"] = "Округлые формы, как на medusa_b1: скруглённые углы комнат, полукруглые торцы залов (апсиды), многоугольные возвышения в одну-две ступени — под предметом или посреди зала. Нет — комнаты прямоугольные, как раньше",
        ["scr.round.few"] = "Немного",
