        ["scr.round.many"] = "Много",
        ["scr.round.corners"] = "Скруглённые углы",
        ["scr.round.corners.tip"] = "Угол комнаты или зала заполняется по дуге радиусом в две-три клетки",
        ["scr.round.apses"] = "Полукруглые торцы залов",
        ["scr.round.apses.tip"] = "Короткий конец зала или комнаты шириной от 4 до 8 клеток делается полукруглым, как торцы залов medusa_b1",
        ["scr.round.podiums"] = "Круглые возвышения",
        ["scr.round.podiums.tip"] = "Восьмиугольное возвышение в зале на ступень над полом, при «Заметно» и «Много» — со второй ступенью внутри; встаёт под предмет зала (предмет — сверху, как на сцене medusa_b1) или на свободное место",
        ["gate.round shapes"] = "Скругления — как заказано: скруглённые углы, полукруглые торцы, возвышения",
        ["gate.buttons clear"] = "Кнопки паверапов свободны: ни одна не утоплена в столбик, пилястру или украшение",
        ["scr.pw"] = "Доступность главных предметов",
        ["scr.pw.tip"] = "Где лежат квад, мега, неуязвимость, красная броня. Просто — на постаменте под своим светом; средне — в нише в стене, приподнятой над полом: в неё запрыгивают; сложно — в нише за дверью, которую открывает кнопка на стене; смешанно — самый ценный сложно, остальные средне",
        ["scr.pw.easy"] = "Просто: на постаменте",
        ["scr.pw.medium"] = "Средне: в нише, куда запрыгнуть",
        ["scr.pw.hard"] = "Сложно: за дверью с кнопкой",
        ["scr.pw.mixed"] = "Смешанно",
        ["scr.prize"] = "Как достаются призы",
        ["scr.prize.tip"] = "Рельсотрон, мега, квад, неуязвимость, красная броня должны доставаться усилием, как на известных картах: за рельсотроном на q2dm1 плывут, на ztn2dm3 прыгают, на q2duel5 идут под обстрелом с трёх сторон. Как на известных картах — способ для каждого приза выбирается так же часто, как на известных картах q2dm, q2duel, q2rdm, ztn2dm и других; в нишах — в нише в стене, куда запрыгивают (самый ценный — за дверью с кнопкой); под водой — за каждым призом нырять или плыть; на открытом месте — оружие и броня посреди зала, куда ведут три прохода и больше, под обстрелом",
        ["scr.prize.people"] = "Как на известных картах",
        ["scr.prize.nooks"] = "В нишах: запрыгнуть, дверь с кнопкой",
        ["scr.prize.water"] = "Под водой: нырять, плыть",
        ["scr.prize.exposed"] = "На открытом месте под обстрелом",
        ["scr.under"] = "Призов под водой",
        ["scr.under.tip"] = "Сколько призов достаются только вплавь: в отдельной комнате, куда из глубокого бассейна ведёт подводная труба 384–768 единиц под полами (как рельсотрон на q2dm1: труба выходит в бассейн самой комнаты, другого входа нет), или на дне глубокого бассейна (как квад на q2dm2). Самые ценные — первыми. Если воды не заказано, для приза делается один бассейн",
        ["scr.spacing"] = "Ценные предметы друг от друга",
        ["scr.spacing.tip"] = "Оружие, броня и усилители не лежат рядом: у взятого предмета должна быть ценность подбора. Как на известных картах — две брони не ближе 600 единиц и 3,4 с ходьбы, оружие от оружия не ближе 300 единиц и 1,5 с, оружие от брони не ближе 350 единиц и 1,7 с (так держат три из четырёх предметов на известных картах); просторнее — по середине известных карт: броня от брони 800 единиц и 4,7 с",
        ["scr.spacing.people"] = "Как на известных картах",
        ["scr.spacing.wide"] = "Просторнее",
        ["scr.practice"] = "Чьи приёмы раскладки",
        ["scr.practice.tip"] = "С каких известных карт брать расстояния между ценными предметами и способы доставать призы. Это не копия карты: берутся только приёмы — как далеко друг от друга и как заработать приз",
        ["scr.practice.mix"] = "Все известные карты",
