        ["scr.tex"] = "Текстуры",
        ["scr.tex.tip"] = "Как у известных карт — отделка одной из отмеченных ниже карт (не отмечено ни одной — одной из известных карт, по которым настроен генератор): её текстуры стен, пола и потолка, бордюры, лампы и цвет света; карту выбирает номер варианта. По выбранным картам — отделка всех отмеченных вместе (только текстуры, ни одной их постройки); смешанно — стены и пол по картам, потолки и бордюры тёмными текстурами генератора; сгенерированные студией — свои текстуры студии по параметрам ниже (тема, цвет, износ, размер деталей, рельеф)",
