        ["scr.label.gen"] = "с нуля, свои текстуры: {0}",
        ["scr.gen.theme"] = "Тема своих текстур",
        ["scr.gen.theme.tip"] = "Из чего сделаны стены, пол и бордюры. Техника — металлические панели, заклёпки, решётки, плитка; готика — камень, кирпич, скала; завод — заклёпки, бетон, решётки, полосы «осторожно»; бункер — бетон, панели, плитка, кирпич; снег и лёд — снег, лёд, камень под снегом, доски; лес — кора, мох, доски, булыжник; город — фасады с окнами, асфальт с разметкой, кирпич, бетон; другая планета — кратеры, кристаллы, светящиеся прожилки; фэнтези — булыжник, камень, доски, руны, золотой орнамент; пустыня — песок с рябью, песчаник, плитка, руны; ад — скала с лавой в трещинах, тёмный камень, кирпич. По умолчанию тему выбирает номер варианта; цвет «по номеру варианта» у снега, леса, города, планеты, фэнтези, пустыни и ада — их собственный",
