        ["strip.time"] = "{0} из {1} мин",
        ["home.sub"] = "Новые карты Quake II — из готовых и с нуля · версия {0}",
        ["home.intro1"] = "MAPGEN Studio делает новые карты Quake II — из уже существующих или с нуля. Из готовой: вы выбираете карту-основу — например, q2dm1 — и говорите, насколько новая карта должна от неё отличаться. С нуля: вы задаёте, на сколько игроков карта, сколько в ней уровней, лифтов и воды, какое оружие и в каком стиле, — и генератор строит её сам. Студия показывает, как идёт работа, складывает готовые карты в библиотеку, снимает для них обложки и одним нажатием кладёт карту в игру.",
        ["home.intro2"] = "Из готовой карты генератор берёт основу и шаг за шагом переделывает её — растягивает и сдвигает её части, прокапывает новые проходы, пристраивает комнаты, двухэтажные залы, мосты, окна и водоёмы, перестраивает стены, полы и лестницы. С нуля он сначала строит каркас — помещения, уровни, переходы и места предметов по правилам известных карт — и собирает из него карту. Каждая правка собирается в настоящую карту и проверяется: можно ли пройти везде, достижимы ли все предметы и места появления, нет ли дыр наружу. Правки, не прошедшие проверку, отбрасываются, поэтому на выходе всегда играбельная карта.",
