        ["gen.creative"] = "Размах переделок",
        ["gen.creative.desc"] = "Сколько и каких новых частей строить. «По умолчанию» — решает генератор по похожести.",
        ["gen.creative.tip"] = "Числа здесь — сколько генератор постарается построить; если на карте нет места, будет меньше",
        ["gen.default"] = "По умолчанию",
        ["gen.opt.digs"] = "Новые проходы",
        ["gen.opt.digs.tip"] = "Сколько новых тоннелей и лестниц прокопать между помещениями",
