        ["gen.opt.storeys.tip"] = "Сколько комнат с галереей и лестницей на второй уровень",
        ["gen.opt.spans"] = "Мосты над ареной",
        ["gen.opt.spans.tip"] = "Сколько мостов перекинуть между галереями над открытым пространством",
        ["gen.opt.liquids"] = "Жидкости",
        ["gen.opt.liquids.tip"] = "Заменить жидкости основы другими — и по виду, и по свойствам: в лаве горят, в кислоте разъедает, в воде плавают. Замена, после которой место не пройти, отклоняется",
