        ["gen.liquids.mix"] = "Перемешать: каждый водоём — другой жидкостью",
        ["gen.opt.decor"] = "Украшения на стенах",
        ["gen.opt.decor.tip"] = "Светильники и украшения, которые генератор находит на стенах основы и повторяет в своих тоннелях: сколько их вешать",
        ["gen.decor.none"] = "Без украшений",
        ["gen.decor.few"] = "Мало",
        ["gen.decor.many"] = "Много",
        ["gen.decor.most"] = "Очень много",
        ["gen.opt.new_water"] = "Новая вода",
        ["gen.opt.new_water.tip"] = "Сколько комнат залить новой водой: доля тех, где можно опустить пол под воду. 0 — новой воды нет совсем (и уровень имеющихся водоёмов не поднимается), 100 — все такие комнаты. «По умолчанию» — решает генератор",
        ["gen.opt.new_slime"] = "Новая кислота",
        ["gen.opt.new_slime.tip"] = "Сколько комнат залить кислотой: 0 — нет, 100 — все, где можно (кроме мест у точек появления). «По умолчанию» — решает генератор",
        ["gen.opt.new_lava"] = "Новая лава",
        ["gen.opt.new_lava.tip"] = "Сколько комнат залить лавой: 0 — нет, 100 — все, где можно (кроме мест у точек появления). «По умолчанию» — решает генератор",
        ["kind.reliquid"] = "другая жидкость",
        ["run.plan.reliquids"] = ", замен жидкости {0}",
        ["run.plan.stairways"] = ", пристроек-лестниц {0}",
        ["run.plan.destruction"] = "; разрушения {0} % — после правок и проверок",
        ["gen.opt.stairways"] = "Пристройки-лестницы",
        ["gen.opt.stairways.tip"] = "Сколько площадок с лестницами построить: у стен комнат и отдельно стоящих на открытом полу, высотой 96–192, на площадке предмет, а у стены она бывает и входом на уступ карты. Мест может оказаться меньше — тогда площадок меньше, это будет сказано",
        ["gen.stairways.none"] = "Нет",
        ["gen.opt.destruction"] = "Разрушения",
        ["gen.opt.destruction.tip"] = "Какая доля уровня разрушена: трещины, обломки, воронки, проломы, отбитые края, обвалы потолка, завалы. 0 — без разрушений (карта как обычно, со всеми проверками проходимости), 100 — почти весь уровень. Точки появления всегда свободны; проходимость при разрушениях не гарантируется. Правая половина регулятора — больше 100 %, до ×100: растёт объёмное — камни и обломки (и на открытом полу), воронки, проломы, отбитые края, обвалы, завалы — сколько вместит формат карты Quake 2 (маленькой карте — больше, большой — меньше); трещины и пятна остаются как на 100 %; описание карты скажет, сколько заказано и сколько построено",
        ["gen.destruction.none"] = "Без разрушений",
        ["gen.opt.remodels"] = "Перестройка основы",
        ["gen.opt.remodels.tip"] = "Сколько раз изменить саму карту-основу, а не пристраивать к ней: стена комнаты сдвигается внутрь, стена поворачивается под углом, вдоль стены поднимается терраса со ступенями. «По умолчанию» — по похожести (чем меньше похожесть, тем больше перестроек). Мест бывает меньше — тогда сделано меньше, и это будет сказано",
        ["gen.remodels.none"] = "Нет",
        ["run.plan.remodels"] = ", перестроек основы {0}",
        ["gen.opt.blocks"] = "Блоки в комнатах",
        ["gen.opt.blocks.tip"] = "Сколько блоков поставить в комнатах самой основы: коробка, Г-образный, крест, восьмигранник или круглый, от 64 до 192 в поперечнике, повёрнутые на разные углы; низкие — запрыгнуть (32–64), высокие — укрытие (96–128); у стены или отдельно, из материала комнаты. «По умолчанию» — по похожести. Мест бывает меньше — тогда блоков меньше, и это будет сказано",
        ["run.plan.blocks"] = ", блоков в комнатах {0}",
        ["gen.opt.floor_shifts"] = "Пол: помосты и каналы",
        ["gen.opt.floor_shifts.tip"] = "Сколько раз изменить пол самой основы: поднять помост со ступенями со всех сторон (коробка или восьмигранник, 32–80 высотой) или опустить канал поперёк пола (32–64 глубиной) с лестницами на обоих концах. Канал копается только там, где под полом нет другого помещения. «По умолчанию» — по похожести; в первую очередь арена",
