        ["scr.prize"] = "How the prizes are earned",
        ["scr.prize.tip"] = "The railgun, mega, quad, invulnerability and body armour are earned with an effort, as on well-known maps: q2dm1's railgun is swum for, ztn2dm3's jumped for, q2duel5's taken under fire from three sides. As on well-known maps - each prize's way chosen as often as well-known maps (q2dm, q2duel, q2rdm, ztn2dm and others) take it; in nooks - a nook in the wall one jumps into (the most valuable behind a door with a button); under water - each prize dived or swum for; in the open - the weapon and the armour in the middle of a hall three ways or more lead into, under fire",
        ["scr.prize.people"] = "As on well-known maps",
        ["scr.prize.nooks"] = "In nooks: jump in, a door with a button",
