        ["scr.prize.exposed"] = "In the open under fire",
        ["scr.under"] = "Prizes under water",
        ["scr.under.tip"] = "How many prizes are taken only by a swim: in a room of their own a tube under water 384-768 units long leads to from a deep pool under the floors (as q2dm1's railgun: the tube comes up in the room's own pool, there is no other way in), or at a deep pool's bottom (as q2dm2's quad). The most valuable first. With no water asked, one pool is made for the prize",
