        ["run.stages"] = "Progress",
        ["gen.warp"] = "The base's frame",
        ["gen.warp.desc"] = "The generator first changes the base itself, and only then builds onto it: it stretches and squeezes the base's parts unequally. A map made larger grows as tall, in proportion; the steps and ledges that could no longer be climbed get gentle ramps in front of them, and the lifts and jump pads follow.",
        ["gen.warp.tip"] = "The map is cut along its length and width into several parts, and each part is stretched or squeezed in its own way: one room becomes twice as long, the passage beside it shorter, the yard wider. The generator places the cuts itself and never through doors, lifts, trains and their paths. It builds the stretched map and checks the walk once, before the first edit; if it does not pass, it tries a milder one",
        ["gen.warp.size"] = "Map size",
        ["gen.warp.size.tip"] = "The new map's area against the base's, 10 to 1000 %. 100 % - the same size. The map gets as much as it can take: no part is squeezed so far that a passage becomes narrower than a player, and the map stays inside the limits the game holds",
        ["gen.warp.size.value"] = "{0} %",
        ["gen.warp.shape"] = "Unequal proportions of the parts",
        ["gen.warp.shape.tip"] = "0 - the whole map is stretched evenly. The further right, the more the parts differ from each other: at 100 % some parts are nearly twice the mean, others shorter. This is what changes the frame itself",
        ["gen.warp.shape.value"] = "{0} %",
        ["gen.warp.shift"] = "Shift of the parts",
        ["gen.warp.shift.tip"] = "The map's parts slide sideways against each other: the rooms of one part stand moved over against the next one's, and the passages between them bend - another layout of the rooms. Floors stay level, walls upright; parts with doors, lifts and trains move whole, not skewed. 0 - no shift",
        ["gen.warp.shift.value"] = "{0} %",
        ["gen.warp.turn"] = "Turn of the base",
        ["gen.warp.turn.tip"] = "The whole base is turned or mirrored: the same places end up on other sides. Doors, lifts, jump pads, the players' facing at the start and the textures turn with it. «By the seed» - the generation's seed chooses",
        ["gen.warp.turn.none"] = "As in the base",
        ["gen.warp.turn.90"] = "Turn by 90°",
        ["gen.warp.turn.180"] = "Turn by 180°",
        ["gen.warp.turn.270"] = "Turn by 270°",
        ["gen.warp.turn.mirror"] = "Mirror",
        ["gen.warp.turn.seed"] = "By the seed",
        ["gen.warp.height"] = "Ceiling height",
        ["gen.warp.height.tip"] = "Over the proportional height: everything above the highest place a player can stand is lifted further - the halls of the top level grow taller, and the sky with them. 100 % - in proportion to the map's size",
        ["gen.warp.height.value"] = "{0} %",
        ["run.warp.ok"] = "The base's frame changed: area {0} % of the original, parts stretched from {1} to {2} times; the map is built and walkable",
        ["run.warp.no"] = "A stretched variant (area {0} %, parts from {1} to {2} times) did not pass the walk - trying a milder one",
        ["run.warp.kept"] = "The base's frame was kept: the stretched map did not pass the check, the generation goes on the original base",
        ["run.warp.height.cut"] = "The ceilings rose to {0} % of the {1} % asked: the game's coordinates hold no more",
        ["run.warp.height.kept"] = "The ceilings stay in proportion: the map with taller ceilings did not pass the check",
        ["gen.grp.rooms"] = "New rooms",
        ["gen.grp.rooms.desc"] = "What the generator builds onto the base: passages, annexes, halls, bridges and stairways. «Default» - the generator decides by the likeness.",
        ["gen.grp.liquids"] = "Water, slime, lava",
        ["gen.grp.liquids.desc"] = "The base's liquids and new pools.",
        ["gen.grp.base"] = "The base rebuilt",
        ["gen.grp.base.desc"] = "What changes in the base's own rooms: walls, blocks, the floor, stairs, ornaments.",
        ["gen.grp.ruin"] = "Ruin",
        ["gen.grp.ruin.desc"] = "How far the map is ruined.",
        ["gen.creative"] = "Scope of the changes",
        ["gen.creative.desc"] = "How many new parts to build and of what kind. «Default» - the generator decides by the likeness.",
        ["gen.creative.tip"] = "The numbers are what the generator tries to build; with no room on the map there are fewer",
        ["gen.default"] = "Default",
        ["gen.opt.digs"] = "New passages",
        ["gen.opt.digs.tip"] = "How many new tunnels and stairs to dig between rooms",
        ["gen.opt.annexes"] = "Annex rooms with pickups",
        ["gen.opt.annexes.tip"] = "How many new rooms holding a pickup to add to the map",
        ["gen.opt.annex_size"] = "Annex size",
        ["gen.opt.annex_size.tip"] = "How big to make the new rooms",
        ["gen.opt.storeys"] = "Two-storey rooms",
        ["gen.opt.storeys.tip"] = "How many rooms with a gallery and stairs to an upper level",
        ["gen.opt.spans"] = "Bridges over the arena",
        ["gen.opt.spans.tip"] = "How many bridges between galleries over open space",
        ["gen.opt.liquids"] = "Liquids",
        ["gen.opt.liquids.tip"] = "Turn the base's liquids into others - look and harm both: lava burns, slime eats, water is swum in. A swap that leaves a place unreachable is refused",
        ["gen.default.liquids"] = "Default - as in the base",
        ["gen.liquids.water-lava"] = "Water → lava",
        ["gen.liquids.water-slime"] = "Water → slime",
        ["gen.liquids.lava-water"] = "Lava → water",
        ["gen.liquids.slime-water"] = "Slime → water",
        ["gen.liquids.lava-slime"] = "Lava → slime",
        ["gen.liquids.slime-lava"] = "Slime → lava",
        ["gen.liquids.mix"] = "Mix: each pool another liquid",
        ["gen.opt.decor"] = "Wall decorations",
        ["gen.opt.decor.tip"] = "The lamps and ornaments the generator finds on the base's walls and repeats in its tunnels: how many to hang",
        ["gen.decor.none"] = "None",
        ["gen.decor.few"] = "Few",
        ["gen.decor.many"] = "Many",
        ["gen.decor.most"] = "Very many",
        ["gen.opt.new_water"] = "New water",
        ["gen.opt.new_water.tip"] = "How many rooms to fill with new water: the share of those whose floor can go under water. 0 - no new water at all (and no pool raised), 100 - every such room. «Default» - the generator decides",
        ["gen.opt.new_slime"] = "New slime",
        ["gen.opt.new_slime.tip"] = "How many rooms to fill with slime: 0 - none, 100 - every room it can (away from the starts). «Default» - the generator decides",
        ["gen.opt.new_lava"] = "New lava",
        ["gen.opt.new_lava.tip"] = "How many rooms to fill with lava: 0 - none, 100 - every room it can (away from the starts). «Default» - the generator decides",
        ["kind.reliquid"] = "another liquid",
        ["run.plan.reliquids"] = ", {0} liquid swaps",
        ["run.plan.stairways"] = ", {0} stairway annexes",
        ["run.plan.destruction"] = "; destruction {0} % - after the edits and the checks",
        ["gen.opt.stairways"] = "Stairway annexes",
        ["gen.opt.stairways.tip"] = "How many platforms with stairs to build: against rooms' walls and standing free on open floor, 96-192 up, a pickup on each, or, by a wall, a way onto a ledge of the map. A map may offer fewer places - then fewer platforms, and it is said",
        ["gen.stairways.none"] = "None",
        ["gen.opt.destruction"] = "Destruction",
        ["gen.opt.destruction.tip"] = "How much of the level is destroyed: cracks, rubble, craters, breaches, broken edges, fallen ceilings, blocked corridors. 0 - none (the map as usual, every passage check), 100 - almost the whole level. The starts are always free; with destruction passage is not guaranteed. The slider's right half - past 100 %, up to ×100: the 3D ruin grows - stones and debris (on open floor too), craters, breaches, broken edges, falls, blockages - as much as the Quake 2 map format holds (a small map more, a large one less); the cracks and stains stay as at 100 %; the map's description says how much was asked and how much was built",
        ["gen.destruction.none"] = "None",
        ["gen.opt.remodels"] = "Remodel the base",
        ["gen.opt.remodels.tip"] = "How many times to change the base map itself rather than build onto it: a room's wall moved in, a wall turned at an angle, a terrace with steps raised along a wall. «Default» goes by the likeness (the less alike, the more remodels). A map may offer fewer places - then fewer are made, and it is said",
        ["gen.remodels.none"] = "None",
        ["run.plan.remodels"] = ", {0} remodels of the base",
        ["gen.opt.blocks"] = "Blocks in the rooms",
        ["gen.opt.blocks.tip"] = "How many blocks to stand in the base's own rooms: a box, an L, a cross, an octagon or a round one, 64 to 192 across, turned at different angles; low ones to climb (32-64), high ones a cover (96-128); against a wall or free, in the room's own material. «Default» goes by the likeness. A map may offer fewer places - then fewer blocks, and it is said",
        ["run.plan.blocks"] = ", {0} blocks in the rooms",
        ["gen.opt.floor_shifts"] = "Floor: daises and channels",
        ["gen.opt.floor_shifts.tip"] = "How many times to change the base's own floor: raise a dais stepped on every side (a box or an octagon, 32-80 high) or sink a channel across the floor (32-64 deep) with a flight at both ends. A channel is dug only where no other room lies under the floor. «Default» goes by the likeness; the arena first",
        ["run.plan.floor_shifts"] = ", {0} floor changes",
        ["gen.opt.stair_reshapes"] = "Rebuild the base's stairs",
        ["gen.opt.stair_reshapes.tip"] = "How many of the base's own stairs to rebuild in another shape between the same two floors: the old flight becomes a landing, reached by a half-round foot of steps or by a side flight. It needs open flat floor in front of the stair; on bases without it fewer are made, and it is said",
        ["run.plan.stair_reshapes"] = ", {0} stairs rebuilt",
        ["gen.opt.halls"] = "Halls on long passages",
        ["gen.opt.halls.tip"] = "How many widened halls on long new passages",
        ["gen.size.small"] = "Small (256 × 256)",
        ["gen.size.medium"] = "Medium (384 × 384)",
        ["gen.size.large"] = "Large (512 × 512)",
        ["gen.size.halls"] = "Halls (768 × 768)",
        ["gen.size.niches"] = "Niches (128 × 160): step in, take it",
        ["run.base"] = "Base: {0}",
        ["run.plan.made"] = "In the plan: {0} new passages, {1} annex rooms, {2} two-storey rooms, {3} bridges, {4} pools, {5} windows",
        ["run.base.grafts"] = "Base: {0}; rooms may come from: {1}",
        ["scheme.tab"] = "Plan",
        ["scheme.wait"] = "The plan appears once the base map is built",
        ["scheme.on"] = "Draw the plan",
        ["scheme.off"] = "The plan is off",
        ["scheme.full"] = "Full screen",
        ["scheme.full.tip"] = "The plan on the whole screen, the run over it; Esc to go back",
        ["scheme.back"] = "Back to the Studio",
        ["scheme.back.tip"] = "Close the full-screen map and return to the Studio's window (or Esc)",
        ["scheme.cut"] = "Storeys up to",
        ["scheme.cut.all"] = "all",
        ["scheme.cut.at"] = "up to {0}",
        ["scheme.legend"] = "The map in 3D. Left button to turn, right to move, wheel nearer/farther, double click for the view from above. Blinking blue - an edit being tried; red - refused (fades in 10 s); green - accepted, then brown; teal with a label - the base map itself changed (a wall moved or turned, a terrace, a block, a dais, a room rebuilt, a new opening and so on) while the edits go on; after them it fades as the green does. Floors lighter the higher; water blue, lava orange, slime green, lifts and doors lilac. Weapons yellow triangles, armour cyan diamonds, health white crosses, ammo grey dots, power-ups violet circles, spawns white rings, teleporters pink rings.",
        ["scheme.top"] = "From above",
        ["scheme.trying"] = "being tried",
        ["scheme.top.tip"] = "The whole map from above (or double click)",
        ["scheme.slant"] = "3D",
        ["scheme.slant.tip"] = "The whole map, slanting",
        ["load.title"] = "Load",
        ["load.cpu"] = "Processor",
        ["load.ram"] = "Memory",
        ["load.gpu"] = "Graphics card",
        ["load.vram"] = "Video memory",
        ["load.gen.cpu"] = "Generator - processor",
        ["load.gen.ram"] = "Generator - memory",
        ["run.attempts"] = "Edits: {0} accepted; {1} of {2} builds; {3} considered",
        ["run.attempts.time"] = "Edits: {0} accepted; {1} builds; {2} considered; the generation takes up to {3} min",
        ["run.plan.value"] = "The plan gives at most ≈ {0}% difference with {1} builds; {2}% is asked",
        ["run.plan.value.tip"] = "Before its first build the generator checks every edit of the plan on the geometry itself and works out how many cubes of the base it would change. This is the sum of the best of them for the builds left: the plan gives no more",
        ["run.plan.exhausted"] = "The plan ran out: no new edits - the generation goes on to finish the map",
        ["run.ladder"] = "How the edits went: {0} did not fit the map and {1} were refused by the check before the build - no build; {2} had been tried; {3} kept for the end; {4} built, the walk worked out whole {5} times, for the rest only around the edit",
        ["run.tried.before"] = "Edits already refused on this map were not tried again: {0}",
        ["run.attempts.tail"] = "; then liquids swapped, item swaps and rooms of other maps: {0} of {1}",
        ["run.attempts.wait"] = "Edits: the plan is still being made",
        ["run.attempts.tip"] = "How many trial builds of the map are done of those allowed",
        ["run.likeness"] = "The map already differs from the base by {0}%, {1}% is asked (the more, the less like the base)",
        ["run.likeness.tip"] = "How far the new map already is from the base, against what was asked. The difference is counted on the base itself: its volume is cut into cubes 32 units a side, and the difference is the share of the cubes where something changed - rock became air or the other way round, a floor or a wall moved, a height, a player's way or a repeated pattern changed. An annex outside the base adds to it only where it cuts into the base; a remodel of the base itself adds the most.",
